#include "geometry/halfplane.hpp"
namespace cg=cp_geometry;
std::vector<cg::HalfPlane> h{{-1,0,0},{0,-1,0},{1,0,4},{0,1,3}};
// 0<=x<=4, 0<=y<=3
auto region=cg::half_plane_intersection(h);
assert(region.kind==cg::RegionKind::POLYGON);
auto area=cg::polygon_area(region.polygon); // 12
